(function () {
'use strict';
/*
 * validation.js —— 篮球女孩梦工场 的「充分校验」层
 *  - validateGameState(G) : 校验运行期游戏状态结构（数值类型/范围/必填字段），不抛异常，返回报告
 *  - assertGameState(G)   : 强校验，发现结构性错误时抛异常（用于服务端硬失败）
 *  - validateSave(obj)    : 校验存档对象（含 saveVer 版本匹配）
 *  - validateAction(name,args): 校验动作名与参数形态
 * 纯函数、零依赖、可在浏览器与 Node 双端复用。
 */

// 数值型状态字段及其合法区间（保守阈值，仅拦截明显异常，不误伤正常成长）
// 数值型状态字段及其合法区间（保守阈值，仅拦截明显异常，不误伤正常成长上限）
const NUM_FIELDS = {
  height: [80, 240],
  skill: [1, 420],
  stamina: [0, 200],
  strength: [1, 420],
  agility: [1, 420],
  pop: [-50, 400],
  study: [0, 200],
  conf: [0, 200],
  speed: [1, 420],
  shoot: [1, 420],
  pass: [1, 420],
  dribble: [1, 420],
  rebound: [1, 420],
  block: [1, 420],
  steal: [1, 420],
  iq: [1, 420],
  leadership: [0, 200],
  ment: [0, 200],
  pot: [1, 200],
  awa: [1, 200],
  aura: [0, 200],
  energy: [0, 200],
  fame: [0, 100000],
};
const SCREENS = new Set([
  'title', 'dream', 'school', 'school2', 'transfer', 'main', 'event',
  'locker', 'prematch', 'match', 'league', 'cup', 'ending', 'lineup',
]);

function isNum(x) { return typeof x === 'number' && isFinite(x); }

function validateGameState(G) {
  const errors = [];
  const warnings = [];
  if (G === null || typeof G !== 'object') {
    errors.push('G 不是对象');
    return { ok: false, errors, warnings, version: 0 };
  }
  // 必填顶层字段
  if (typeof G.screen !== 'string') errors.push('G.screen 缺失或非字符串');
  else if (!SCREENS.has(G.screen)) warnings.push('未知 screen: ' + G.screen);
  if (!isNum(G.season)) errors.push('G.season 非数值');
  if (typeof G.name !== 'string') errors.push('G.name 缺失');
  if (typeof G.template !== 'string') errors.push('G.template 缺失');

  // 数值字段
  const stats = G.stats;
  if (!stats || typeof stats !== 'object') errors.push('G.stats 缺失或非对象');
  else {
    for (const k in NUM_FIELDS) {
      if (!(k in stats)) { warnings.push('stats 缺少 ' + k); continue; }
      const v = stats[k];
      if (!isNum(v)) { errors.push('stats.' + k + ' 非数值: ' + JSON.stringify(v)); continue; }
      const [lo, hi] = NUM_FIELDS[k];
      if (v < lo || v > hi) warnings.push('stats.' + k + ' 超出常见区间 [' + lo + ',' + hi + ']: ' + v);
    }
  }

  // 结构字段
  if (G.rivals !== undefined && !Array.isArray(G.rivals)) errors.push('G.rivals 应为数组');
  if (G.lineup !== undefined && !Array.isArray(G.lineup)) errors.push('G.lineup 应为数组');
  if (G.history !== undefined && !Array.isArray(G.history)) errors.push('G.history 应为数组');
  if (G.teamMorale !== undefined && !isNum(G.teamMorale)) errors.push('G.teamMorale 非数值: ' + JSON.stringify(G.teamMorale));

  return { ok: errors.length === 0, errors, warnings, version: G.saveVer || 0 };
}

function assertGameState(G) {
  const r = validateGameState(G);
  if (!r.ok) throw new Error('游戏状态校验失败: ' + r.errors.join('; '));
  return r;
}

function validateSave(obj, expectedVer) {
  const errors = [];
  const warnings = [];
  if (!obj || typeof obj !== 'object') { errors.push('存档不是对象'); return { ok: false, errors, warnings }; }
  if (typeof obj.saveVer === 'undefined') errors.push('存档缺少 saveVer（旧版格式）');
  else if (expectedVer !== undefined && obj.saveVer !== expectedVer)
    errors.push('存档版本不匹配: 期望 ' + expectedVer + ' 实际 ' + obj.saveVer);
  if (!obj.g || typeof obj.g !== 'object') errors.push('存档缺少 g 状态对象');
  else {
    const sub = validateGameState(obj.g);
    if (!sub.ok) errors.push('存档内状态非法: ' + sub.errors.join('; '));
    sub.warnings.forEach(w => warnings.push(w));
  }
  return { ok: errors.length === 0, errors, warnings };
}

function validateAction(name, args) {
  const errors = [];
  if (typeof name !== 'string' || !name) errors.push('动作名必须是非空字符串');
  if (args !== undefined && !Array.isArray(args)) errors.push('动作参数必须是数组');
  return { ok: errors.length === 0, errors };
}

window.__V = { validateGameState, assertGameState, validateSave, validateAction, SCREENS, NUM_FIELDS };

})();

