var clamp = function(v,a,b){return Math.max(a,Math.min(b,v));};
/* 体力上限：随年龄成长（12 岁约 60，18 岁成年达 100），训练可扩充，最大 140 */
function natCap(age){ return clamp(60 + (age-12)/6*40, 60, 100); }
function stamCap(){ return Math.min(140, natCap(G.age) + (G.stamCapBonus||0)); }
/* 训练随机系数：体力长期过低（低于上限 30% / 20%）时，成长等随机增益被压到 0.8~0.95（更低则 0.7~0.9） */
function growthRandom(){
  var ratio = G.stats.stamina / stamCap();
  if(ratio < 0.20) return 0.70 + rng()*0.20;   // 0.70~0.90
  if(ratio < 0.30) return 0.80 + rng()*0.15;   // 0.80~0.95
  return 1 + (rng()*0.70 - 0.30);              // 正常 0.70~1.40
}
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;var t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
var _rngGen = Math.random;
function reseedRNG(seed){ _rngGen = mulberry32((seed >>> 0) || 1); }
var rng = function(){ return _rngGen(); };
/* 正态分布（Box-Muller），用于 3σ 比分 */
function gauss(mean, sd){
  var u=0,v=0; while(u===0)u=rng(); while(v===0)v=rng();
  var n=Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);
  return mean + n*sd;
}

