/* ================= 主角开局天赋掷骰 =================
   三个职业各自有一份「基准」：BASE_STATS + tpl.mod（初始属性偏置）+ tpl.train（训练倍率）。
   每次开局都在这份基准上重新掷骰，让每一周目都是一个不同的 build：
   · 成长资质 apt[k]：基准 ±30%。掷完做「零和归一」——某项掷高，必有另一项掷低，
     全身资质预算恒定，永远不会出现"全项拉满"或"全项废柴"的开局。
   · 潜力上限 pot[k]：基准 ±30%，且与 apt **负相关**——长得快的天花板低、起步慢的后劲足。
     （pot 直接放大 dimRet 的边际递减阈值，即"这项属性能堆到多高"。）
   这一正一反两条线构成负反馈平衡：短期爽感与长期上限互相对冲，不同开局强度接近但手感迥异。
   · 体质抽签：初始身高 / 体重 / 骨龄全部随机，且**大概率**落在「中等偏上身高 + 晚发育体质」——
     骨龄落后同龄人却已经比同龄人高，意味着生长板闭合更晚、最终身高非常可观（本作主角的设定基调）。 */
var APT_KEYS = ['skill','stamina','strength','agility','pop','study','conf','height'];
var APT_LAB  = {skill:'技术',stamina:'体力',strength:'力量',agility:'敏捷',pop:'人气',study:'学习',conf:'自信',height:'身高'};
function rollTalent(tplKey, r){
  var tpl = TEMPLATES[tplKey] || TEMPLATES.guard;
  // ① 每项掷一个 -0.30 ~ +0.30 的资质偏移（正态，极端值稀有）
  var dev={}, sum=0;
  APT_KEYS.forEach(function(k){ var d=clamp(gaussR(r)*0.17, -0.30, 0.30); dev[k]=d; sum+=d; });
  // ② 零和归一：抹平总偏移 → "有得必有失"的反馈平衡
  var avg = sum/APT_KEYS.length, apt={}, pot={};
  APT_KEYS.forEach(function(k){
    apt[k] = clamp(1 + (dev[k]-avg), 0.70, 1.30);
    pot[k] = clamp(2 - apt[k] + gaussR(r)*0.06, 0.70, 1.30);   // ③ 潜力与资质负相关
  });
  // ④ 本职业的看家本领保底 0.88（后卫不至于手残、中锋不至于没力量），抬升额从其它项等额扣回
  var lift=0;
  for(var tk in tpl.train){ if(apt[tk]!=null && apt[tk]<0.88){ lift += 0.88-apt[tk]; apt[tk]=0.88; } }
  if(lift>0){
    var others = APT_KEYS.filter(function(k){ return !tpl.train[k]; });
    if(others.length) others.forEach(function(k){ apt[k]=clamp(apt[k]-lift/others.length, 0.70, 1.30); });
  }
  // ⑤ 体质抽签
  var tall = r() < 0.78;                                        // 78% 中等偏上身高
  var hRoll = tall ? (2.0 + Math.abs(gaussR(r))*3.6)            // 偏上：+2 ~ +9cm
                   : (gaussR(r)*2.6 - 1.4);                     // 其余：中位线上下
  var late  = r() < 0.72;                                       // 72% 晚发育体质
  var baLag = late ? -(0.8 + r()*1.5) : (r()*1.1 - 0.5);        // 骨龄落后 / 常规
  var growEnd = late ? (19.2 + r()*1.4) : (17.5 + r()*1.1);     // 生长板闭合骨龄
  var baRate  = late ? (0.72 + r()*0.16) : (0.92 + r()*0.22);   // 骨龄推进倍率（1 = 常人 0.25/季）
  if(late) pot.height = clamp(pot.height + 0.10 + r()*0.12, 0.70, 1.45);   // 晚发育 → 身高天花板更高
  var pt = rollPTrait(r);                                       // 主角也和全联盟共用同一套先天特征
  return {apt:apt, pot:pot, late:late, tall:tall,
          ptrait:pt.id, ptraitN:pt.n, ptraitTag:pt.tag,
          hRoll: Math.round(hRoll),
          baLag: Math.round(baLag*10)/10,
          growEnd: Math.round(growEnd*10)/10,
          baRate: Math.round(baRate*100)/100,
          wJit: 0.92 + r()*0.16};
}
