    seasonStats:{g:0,pts:0,reb:0,ast:0,stl:0,blk:0,tov:0,fgm:0,fga:0,w:0,l:0},
    careerStats:{g:0,pts:0,reb:0,ast:0,stl:0,blk:0,tov:0,fgm:0,fga:0,w:0,l:0},
