/* 随机赛程：混合强/中/弱队，乱序；联赛偶尔遭遇王牌校 */
function genSchedule(){
  var pool = G.curTeams.filter(function(t){ return !t.isAce; });
  var arr = pool.map(function(t){
    return {name:t.name, base:t.base, isAce:false, trait:t.trait, roster:t.roster,
      injMul:(rng()<0.16?0.82:1), moraleMul:(rng()<0.30?(rng()<0.5?1.12:0.9):1)};
  });
  arr.sort(function(a,b){ return b.base-a.base; });
  var n=arr.length;
  var strong=arr.slice(0, Math.floor(n*0.25));
  var weak=arr.slice(Math.floor(n*0.70));
  var mid=arr.slice(Math.floor(n*0.25), Math.floor(n*0.70));
  var picks=[];
  picks.push(strong[Math.floor(rng()*strong.length)]);
  picks.push(weak[Math.floor(rng()*weak.length)]);
  while(picks.length<5) picks.push(mid[Math.floor(rng()*mid.length)]);
  if(rng()<0.30){ // 联赛也可能遭遇王牌校（额外硬仗）
    var ace=G.curTeams.filter(function(t){return t.isAce;})[0];
    if(ace) picks[Math.floor(rng()*picks.length)] = {name:ace.name, base:ace.base, isAce:true, trait:ace.trait, roster:ace.roster,
      injMul:(rng()<0.16?0.82:1), moraleMul:(rng()<0.30?(rng()<0.5?1.12:0.9):1)};
  }
  for(var i=picks.length-1;i>0;i--){ var j=Math.floor(rng()*(i+1)); var t=picks[i]; picks[i]=picks[j]; picks[j]=t; }
  return picks;
}
function setupLeague(){
  G.ctx='league';
  G.seasonStats={g:0,pts:0,reb:0,ast:0,stl:0,blk:0,tov:0,fgm:0,fga:0,w:0,l:0};
  G.league={schedule:genSchedule(), idx:0, games:[]};
  G.teamMorale = clamp((G.teamMorale||0) + (rng()-0.5)*0.6, -2, 2);
}

/* 当前可选手策略（根据对手强弱/自身状态上下文筛选 4 个） */
function currentStrats(opp){
  var strong = (oppEff(opp, G.ctx==='cup') > teamPower()*1.06) || opp.isAce;
  var arr = ['balanced'];
  arr.push(strong ? 'focus' : 'aggro');
  arr.push('defense'); arr.push('tempo');
  if(G.injury || G.stats.stamina<38){
    arr = arr.filter(function(x){ return x!=='aggro'; });
    if(arr.indexOf('save')<0) arr.push('save');
  }
  // 保证能"克制"对手本场策略的那套个人策略始终可选
  if(opp.activeStrat && arr.indexOf(opp.activeStrat.counter)<0){
    var c = opp.activeStrat.counter;
    var idx = arr.indexOf('aggro');
    if(idx>=0) arr[idx]=c; else if(arr.length<4) arr.push(c); else arr[arr.length-1]=c;
  }
  return arr.slice(0,4);
}

/* 个人技术统计（得分/篮板/助攻/抢断/盖帽/失误/命中率）
   oppStrat 为对手本场随机策略：会改变你的得分环境（如铁桶压制得分、紧逼制造失误）。
   forcePts：强制个人得分（用于逐节合成后的总分，且必 <= 全队总分）。 */
function genBox(strat, win, oppStrat, forcePts){
  var st=G.stats, w=TEMPLATE_BOX[G.template];
  var oS = oppStrat||null;
  var off=(strat.ptsMul||1)*(oS?(oS.pPtsMul||1):1)*(win?1.04:0.96);
  var fat = (st.stamina<40)? 0.8 : 1;   // 体力不足 20% 能力削弱
  var fgPct=clamp(0.30 + st.skill*0.0045 + st.conf*0.002 + (strat.offMul-1)*0.22, 0.24, 0.68);
  var pts=Math.round(clamp((8 + (st.skill*0.10 + st.agility*0.03 + st.conf*0.03 + st.height*0.02)*off*(0.8+rng()*0.45)), 0, 9999)*fat);
  if(forcePts!=null) pts = forcePts;
  // 约束：个人得分不得超过全队总分
  var capYS = (G.curMatch && G.curMatch.ys!=null) ? G.curMatch.ys : 9999;
  if(pts>capYS) pts = capYS;
  var reb=Math.round((1.5 + st.height*0.05 + st.strength*0.035) * w.reb * (0.8+rng()*0.4) * fat);
  var ast=Math.round((0.8 + st.skill*0.05 + st.agility*0.03) * w.ast * (strat.astMul||1) * (0.7+rng()*0.6) * fat);
  var stl=Math.round((0.4 + st.agility*0.035) * w.stl * (strat.stlMul||1) * (oS?(oS.pStlMul||1):1) * (0.6+rng()*0.8) * fat);
  var blk=Math.round((0.25 + st.height*0.03 + st.strength*0.03) * w.blk * (strat.blkMul||1) * (oS?(oS.pBlkMul||1):1) * (0.5+rng()*0.9) * fat);
  var tov=Math.round(clamp((3.2 - st.skill*0.02 - st.agility*0.012) * (strat.tovMul||1) * (oS?(oS.pTovMul||1):1) * (0.7+rng()*0.6), 0, 12));
  var fga=Math.round(pts*0.85 + 4 + rng()*5);
  var fgm=Math.round(clamp(fga*fgPct, 0, fga));
  if(pts>0 && fgm===0) fgm=1;
  return {pts:pts, reb:reb, ast:ast, stl:stl, blk:blk, tov:tov, fgm:fgm, fga:fga};
}
function accStats(box, win){
  var s=G.seasonStats, c=G.careerStats;
  ['pts','reb','ast','stl','blk','tov','fgm','fga'].forEach(function(k){ s[k]+=box[k]; c[k]+=box[k]; });
  s.g++; c.g++; if(win){ s.w++; c.w++; } else { s.l++; c.l++; }
  if(typeof addRouteScoreFromMatch==='function') addRouteScoreFromMatch(box);
}
/* 比赛完美数据 → 额外成长激励：不同表现类型给不同属性的"分项成长激励"（自信抬升 + 对应属性成长基数抬升，单项封顶 6%） */
function applyPerfMotivation(box, win){
  var M = G.motivation || (G.motivation={skill:0,strength:0,agility:0,pop:0,conf:0,stamina:0});
  var CAP = 0.06;
  function add(key, amt){ if(M[key]!=null) M[key]=Math.min(CAP, M[key]+amt); }
  var cats=[box.pts,box.reb,box.ast,box.stl,box.blk];
  var dd=cats.filter(function(v){return v>=10;}).length;   // 达到两双/三双门槛的项数
  var confAdd=0, motList=[];
  // 各类表现 → 不同属性成长激励
  if(box.pts>=28){ add('skill',0.0025); motList.push('爆分·技术'); }
  if(box.reb>=12){ add('strength',0.0025); motList.push('篮板·力量'); }
  if(box.ast>=10){ add('agility',0.0018); add('pop',0.0018); motList.push('助攻·敏捷/人气'); }
  if(box.stl>=5){ add('agility',0.0018); motList.push('抢断·敏捷'); }
  if(box.blk>=4){ add('strength',0.0018); motList.push('盖帽·力量'); }
  // 综合型数据额外全面激励
  if(dd>=3){ ['skill','strength','agility','pop'].forEach(function(k){ add(k,0.0015); }); confAdd=6; motList.push('三双·全面'); }
  else if(dd===2){ ['skill','strength','agility','pop'].forEach(function(k){ add(k,0.001); }); confAdd=3; }
  else if((box.stl+box.blk)>=6){ confAdd=2; motList.push('防守大闸'); }
  else if(dd===1){ confAdd=1.5; motList.push((box.pts>=10?'得分':box.reb>=10?'篮板':box.ast>=10?'助攻':box.stl>=10?'抢断':'盖帽')+'上双'); }
  if(confAdd>0){
    G.stats.conf=Math.max(0, G.stats.conf+confAdd);
    var pctTxt = ['skill','strength','agility','pop','stamina'].filter(function(k){return (M[k]||0)>0;})
                   .map(function(k){ return ({skill:'技术',strength:'力量',agility:'敏捷',pop:'人气',stamina:'体力'}[k]) + ' +'+(M[k]*100).toFixed(1)+'%'; }).join(' ');
    var label = motList.join(' · ');
    addHighlight('⭐ '+secLabel()+' '+label+'！自信 +'+confAdd+(pctTxt?('，成长激励 '+pctTxt):'')+'（训练中生效）');
    diary(secLabel(), '完美数据：'+label+'。分项成长激励 → '+pctTxt+'。');
  }
}
function maybeInjury(strat, win){
  if(G.resting) return;   // 休战不上场，不触发受伤
  if(G.injury){ G.injury.gamesLeft--; if(G.injury.gamesLeft<=0) G.injury=null; return; }
  // 体力越低越易伤：<40 风险×1.6，<20 再×1.9（约 3 倍）
  var risk=(strat.risk||0) * (G.stats.stamina<40?1.6:1) * (G.stats.stamina<20?1.9:1) * (G.age<14?1.2:1);
  if(rng()<risk){
    var sev=1+Math.floor(rng()*2), games=1+Math.floor(rng()*3);
    G.injury={gamesLeft:games, sev:sev};
    diary(secLabel(), '比赛中意外受伤（伤情 '+sev+'/2），预计休战 '+games+' 场。');
    addHighlight('🩹 意外受伤！后续比赛状态与数据将受影响');
  }
}
function genPostChoices(win, opp){
  var pool=POST_POOL.slice(), out=[];
  if(opp.isAce){ var t=pool.find(function(c){return c.onlyAce;}); if(t) out.push(t); }
  while(out.length<3 && pool.length){
    var i=Math.floor(rng()*pool.length), c=pool.splice(i,1)[0];
    if(c.onlyAce && !opp.isAce) continue;
    out.push(c);
  }
  return out;
}
function applyPostChoice(ch){
  var st=G.stats, e=ch.eff, fr=ch.fr;
  // 仅影响短期状态与友情，不叠加永久养成属性，保持平衡
  if(e.stamina) st.stamina=clamp(st.stamina+e.stamina,0,stamCap());
  if(e.morale) G.teamMorale=clamp((G.teamMorale||0)+e.morale,-3,3);
  if(e.form) G.form=clamp(G.form+e.form+(rng()-0.5)*0.2,-3,3);
  if(e.rel) adjustTeamRel(e.rel*2.5);
  if(fr) for(var fk in fr){
    var fv=fr[fk];
    if(fk==='team'){ adjustTeamRel(fv*2.5); }
    else if(G.friends && G.friends[fk]!=null){ G.friends[fk]=clamp(G.friends[fk]+fv,0,100); }
    pushAxisFeed('friend', fv, FR_NAME[fk]||fk);
  }
  syncAxes();
}

/* 进入下一场（赛前策略界面） */
function beginPrematch(){
  G.resting=false; G.matchStamMod=0;   // 每场重置"休战"标记与强度选择，避免上一场残留
  if(G.ctx==='cup'){
    if(G.cup.advanced===false){ endCup(); return; }
    if(G.cup.idx>=G.cup.playerPath.length){ endCup(); return; }
    G.curOpp=G.cup.playerPath[G.cup.idx];
  } else {
    if(G.league.idx>=G.league.schedule.length){ endLeague(); return; }
    G.curOpp=G.league.schedule[G.league.idx];
  }
  G.prematchStep='time'; G.minutes=0;
  ensureOppRoster(G.curOpp);   // 预生成对手阵容并设定其本场初始体力（非满血）
  rollOppStrat(G.curOpp);   // 开赛前：从对手的两套相互克制策略里随机抽一套
  G.screen='prematch'; render();
}

/* 赛前选择上场时间：每 2 分钟消耗 1 点体力，打满全场（40 分钟）额外消耗，共 30 点 */
function pickMinutes(mins){
  if(G.screen!=='prematch' || G.prematchStep!=='time') return;
  var cost = Math.floor(mins/2);   // 每 2 分钟耗 1 点体力：48→24, 36→18, 24→12, 12→6
  G.stats.stamina = clamp(G.stats.stamina - cost, 0, stamCap());
  G.minutes = mins;
  G.prematchStep='strat';
  render();
}

/* 合并档位：一次选定「上场时间 + 投入强度」（原先分成两个四选一，现合并为一个） */
var LOADOUT = [
  {key:'lo_full', n:'全勤拼命', mins:48, mod: 0.05, hint:'你冲在最前，队友跟着拼命'},
  {key:'lo_main', n:'主力均衡', mins:36, mod: 0,    hint:'主力出场，正常节奏'},
  {key:'lo_rot',  n:'轮换省力', mins:24, mod:-0.05, hint:'轮换登场，队友略省力'},
  {key:'lo_sub',  n:'替补养生', mins:12, mod:-0.20, hint:'少出力，全队省着打'}
];
function loadoutCost(o){ return Math.max(1, Math.round(Math.floor(o.mins/2) / profMul(o.key))); }
function loadoutMod(o){ var pm = profMul(o.key); return o.mod > 0 ? o.mod / pm : o.mod * pm; }
function pickLoadout(key){
  if(G.screen!=='prematch' || G.prematchStep!=='time') return;
  var o = LOADOUT.filter(function(x){ return x.key===key; })[0]; if(!o) return;
  G.stats.stamina = clamp(G.stats.stamina - loadoutCost(o), 0, stamCap());
  G.minutes = o.mins;
  G.matchStamMod = loadoutMod(o);
  profBump(key);
  G.prematchStep = 'strat';
  render();
}
/* 本场"投入强度"选择：个人越拼，队友消耗越多（-20% / -5% / 0 / +5%；不上场 +25% 由 rest 处理） */
var MATCH_INTEN = [
  {key:'easy',    n:'养生',     mod:-0.20, hint:'你少出力，队友省着打'},
  {key:'light',   n:'省着打',   mod:-0.05, hint:'保守消耗，队友略省力'},
  {key:'balance', n:'均衡',     mod:0,     hint:'正常节奏'},
  {key:'hard',    n:'拼尽全力', mod:0.05,  hint:'你冲在前，队友跟着拼命'}
];
function setMatchIntensity(key){
  if(G.screen!=='prematch' || G.prematchStep!=='time') return;
  var it = MATCH_INTEN.filter(function(x){return x.key===key;})[0]; if(!it) return;
  G.matchStamMod = it.mod; render();
}
/* 赛前决策：上场 / 休息。休息 = 本场休战，恢复体力、避免受伤，但队伍战力下降、你无个人数据 */
function prematchDecision(mode){
  if(G.screen!=='prematch' || G.prematchStep!=='time') return;
  if(mode==='rest'){
    G.resting=true; G.minutes=0; G.matchStamMod=0.25;   // 不上场 → 队友多扛，消耗 +25%
    G.stats.stamina = clamp(G.stats.stamina + stamCap()*0.18, 0, stamCap());   // 休战恢复约 18% 体力
    G.prematchStep='strat';
    prematchPick('balanced'); return;   // 以稳健策略模拟本场（你作壁上观）
  }
  render();   // mode==='play'：留在时间选择步，自行选上场时间
}
/* 选策略 → 模拟本场 → 赛果界面 */
function findMateByName(n){
  var arr=(G.teammates||[]).filter(function(p){ return p.name===n; });
  return arr.length?arr[0]:null;
}
function rollDuoBuff(){
  refreshDuos();
  var duos=(G.duos||[]);
  if(!duos.length){ G._duoBuff=null; return; }
  var d=duos[Math.floor(rng()*duos.length)];
  var attr=DUO_ATTR[Math.floor(rng()*DUO_ATTR.length)];
  G._duoBuff={name:d.name, k:attr.k, attrName:attr.n, sentence:attr.s};
}
function applyDuoBuff(){
  rollDuoBuff();
  if(!G._duoBuff) return;
  var k=G._duoBuff.k;
  G._duoBuff._base=G.stats[k];
  G.stats[k]=G.stats[k]*1.10;
  var mt=findMateByName(G._duoBuff.name);
  if(mt){ G._duoBuff._mateUid=mt.uid; G._duoBuff._mateBase=mt.ovr; mt.ovr=mt.ovr*1.10; }
}
function clearDuoBuff(){
  if(!G._duoBuff) return;
  var k=G._duoBuff.k;
  if(G._duoBuff._base!=null) G.stats[k]=G._duoBuff._base;
  if(G._duoBuff._mateUid){
    var mt=findMateByName(G._duoBuff.name);
    if(mt && G._duoBuff._mateBase!=null) mt.ovr=G._duoBuff._mateBase;
  }
  if(G.duoLog){
    G.duoLog.push('你 × '+G._duoBuff.name+' '+G._duoBuff.attrName+' 同场 +10%');
    if(G.duoLog.length>6) G.duoLog.shift();
  }
  G._duoBuff=null;
}
function prematchPick(key){
  if(G.screen!=='prematch') return;
  applyDuoBuff();
  assignMatchMinutes();          // 按档位给每名队友摇定本场上场时间
  var strat=profStrat(key); if(!strat) return;
  var isCup=(G.ctx==='cup'), opp=G.curOpp;
  var formMul=1+G.form*0.05, moraleMul=moraleStrMul();
  var injMul=G.injury?(1-G.injury.sev*0.12):1;
  // 对手本场策略：抬升/压低其战力，并可在你"恰好克制"它时给一点加成
  var oStrat = opp.activeStrat||null;
  var oOffMul = oStrat ? (oStrat.offMul||1) : 1;
  var cf = counterFactor(key, oStrat, opp.trait);   // 特性/战术耦合克制：选对克制→明显分数上克制
  // 对手学校特性方向性攻防：进攻倾向 oppOffMul（>1 其得分涨）、防守强度 oppDefMul（>1 你得分被压）
  var oppTr = TRAIT_BY[opp.trait] || TRAIT_BY.allround;
  var oppOffMul = oOffMul * (oppTr.offMul||1);
  var oppDefMul = (oppTr.defMul||1);
  if(isCup && G.cup.isTwoLeg){
    // 初中杯两回合 = 两场四节制比赛（单节上限 108、罚球 132，四节不设硬上限；逐场、逐节均满足 个人<全队）
    var restMul = G.resting?0.72:1;
    var youE_2 = teamPower()*strat.offMul*formMul*moraleMul*injMul*cf*(G.stats.stamina<40?0.8:1)*restMul;
    var oppE_2 = oppEff(opp,true)*(opp.injMul||1)*(opp.moraleMul||1)*oOffMul;
    applyMatchStamina(G.resting?0:G.minutes, key, opp);
    youE_2 *= avgStaminaFactor(lineupTeammates().concat([{stam:G.stats.stamina, stamMax:stamCap()}]));
    oppE_2 *= avgStaminaFactor(oppStarters(opp));
    var tl=simTwoLeg(youE_2, oppE_2, oppOffMul, oppDefMul);
    // 逐场装饰：生成个人数据 + 四节分布（个人每节 < 全队每节）
    G.curMatch={ys:9999};                 // 临时占位，避免 genBox 误用上一场的 cap
    tl.l1 = decorateTwoLegLeg(tl.l1, strat, oStrat);
    tl.l2 = decorateTwoLegLeg(tl.l2, strat, oStrat);
    G.curMatch=null;
    // 汇总（展示用）：四节相加；个人汇总分 < 全队汇总分
    var aggBox={}; ['pts','reb','ast','stl','blk','tov','fgm','fga'].forEach(function(k){ aggBox[k]=tl.l1.box[k]+tl.l2.box[k]; });
    var res={win:tl.win, ys:tl.ay, os:tl.ao, twoleg:tl, opp:opp.name, isAce:!!opp.isAce, p:0.5, box:aggBox};
    if(G.resting){ ['pts','reb','ast','stl','blk'].forEach(function(k){ aggBox[k]=Math.round(aggBox[k]*0.25); }); }   // 休战：个人数据大幅缩水
    res.qy=[0,0,0,0]; res.qo=[0,0,0,0]; res.qpts=[0,0,0,0];
    for(var qi=0;qi<4;qi++){ res.qy[qi]=tl.l1.qy[qi]+tl.l2.qy[qi]; res.qo[qi]=tl.l1.qo[qi]+tl.l2.qo[qi]; res.qpts[qi]=tl.l1.qpts[qi]+tl.l2.qpts[qi]; }
    res.strat=key; res.stratName=strat.name; res.counterF=cf;
    res.oppRef=opp;
    // 两回合同样给逐节战术：总比分与胜负已定，战术只改体力与个人表现，故结算延后到第 4 节
    res.qopts=[pick4Tactics(),pick4Tactics(),pick4Tactics(),pick4Tactics()];
    res.qtactic=[null,null,null,null];
    res.twoLegPending=true;
    maybeInjury(strat,res.win);
    G.curMatch=res; G.curMatchComm=commentary(res);
    G.matchQuarter=0; res.moments=genMoments(res,key,opp);
    G.screen='match'; render();
    return;
  }
  // 【联赛 / 高中杯 BO5：逐节生成骨架】—— 比分与数据在每节 reveal 时生成，第 4 节 finalize
  var restMul = G.resting?0.72:1;
  var youBaseE = teamPower()*formMul*moraleMul*injMul*(G.stats.stamina<40?0.8:1)*restMul;
  var oppBaseE = oppEff(opp,isCup)*(opp.injMul||1)*(opp.moraleMul||1)*oOffMul;
  applyMatchStamina(G.resting?0:G.minutes, key, opp);
  youBaseE *= avgStaminaFactor(lineupTeammates().concat([{stam:G.stats.stamina, stamMax:stamCap()}]));
  oppBaseE *= avgStaminaFactor(oppStarters(opp));
  var youE0 = youBaseE*strat.offMul*cf;
  var oppE0 = oppBaseE;
  var p = clamp(Math.pow(youE0,1.8)/(Math.pow(youE0,1.8)+Math.pow(oppE0,1.8)) + (strat.winBonus||0) + (rng()-0.5)*0.08, 0.08, 0.92);
  G.curMatch = {
    strat:key, stratName:strat.name, opp:opp.name, isAce:!!opp.isAce, oppRef:opp, oStrat:oStrat, counterF:cf,
    youBaseE:youBaseE, oppBaseE:oppBaseE, p:p, oppOffMul:oppOffMul, oppDefMul:oppDefMul,
    qy:[0,0,0,0], qo:[0,0,0,0], qpts:[0,0,0,0], qopts:[pick4Tactics(),pick4Tactics(),pick4Tactics(),pick4Tactics()], qtactic:[null,null,null,null],
    ys:0, os:0, win:false, box:null, moments:null
  };
  // 逐节独立生成：单节上限 108（罚球 2+1 达 132），四节不设硬上限（具体见 revealQuarter）
  G.matchQuarter=0; G.screen='match'; render();
}
/* 赛后统一回复：主角 / 队友 / 对手，全部按"自身体力上限的 RECOVER_PCT"回复 —— 恢复规则与主角完全一致 */
var RECOVER_PCT = 0.05;
function recoverAfterMatch(){
  G.stats.stamina = clamp(G.stats.stamina + stamCap()*RECOVER_PCT, 0, stamCap());   // 主角：固定首发，按主角体力上限回复
  (G.teammates||[]).forEach(function(p){ var mx=p.stamMax||100; p.stam = clamp((p.stam!=null?p.stam:mx) + mx*RECOVER_PCT, 0, mx); });
  if(G.curOpp && G.curOpp.roster){ G.curOpp.roster.forEach(function(p){ var mx=p.stamMax||100; p.stam = clamp((p.stam!=null?p.stam:mx) + mx*RECOVER_PCT, 0, mx); }); }
}
/* 赛后交流 → 推进（下一场 / 赛季总结 / 杯赛下一轮） */
function matchContinue(idx){
  if(G.screen!=='match') return;
  clearDuoBuff();
  var ch=G.curMatchChoices[idx]; if(ch) applyPostChoice(ch);
  recoverAfterMatch();   // 所有人（主角/队友/对手）按同一规则恢复，与主角一致
  // 成果轴：赢球积累成果（掀翻王牌校额外加分）
  var m0=G.curMatch;
  if(m0){
    if(m0.win){
      var rGain = 1 + (m0.isAce?2:0);
      G.axes.result += rGain;
      pushAxisFeed('result', rGain, m0.isAce?'掀翻王牌校':(G.ctx==='cup'?'杯赛晋级':'比赛获胜'));
      // 挫折后的崛起（才能开花）：上一场崩盘后，这场干脆利落赢回来
      if(G.chokeActive){ G.chokeActive=false; queueAwaken('rise','rise','低谷崛起·觉醒'); }
    } else {
      // 关键战崩盘（挫折）：一定概率触发，埋下"崛起"伏笔
      if(!G.chokeActive && rng()<0.22){
        G.chokeActive=true;
        G.setbacks.push({y:G.year, t:'关键战崩盘'});
        G.eventQueue.push('choke');
      }
    }
  }
  if(G.ctx==='cup'){
    var c=G.cup;
    G.seasonGames = (G.seasonGames||0) + 1;   // 本赛季比赛数 +1（用于成长缩放）
    if(c.isTwoLeg){
      // 【初中杯两回合：单场即定胜负，逻辑不变】
      c.youLog.push(buildCupEntry(G.curMatch, G.curOpp, c.roundNames[c.idx]));
      if(G.curMatch.win){ if(G.curOpp.isAce){ unlock('a_ace'); queueAwaken('aw_ace','aw_ace','屠龙时刻·觉醒'); } c.idx++; }
      else { c.youElim=c.roundNames[c.idx]; c.idx=999; }
      G.curMatch=null; G.curMatchChoices=null; G.curMatchComm=null;
      if(c.idx>=c.playerPath.length || c.youElim || c.advanced===false){ endCup(); }
      else beginPrematch();
    } else {
      // 【高中杯五局三胜：逐场交互系列赛】每场都是四节，先到 3 胜晋级
      c.seriesGames = c.seriesGames||[];
      c.seriesGames.push({ys:G.curMatch.ys, os:G.curMatch.os, win:G.curMatch.win, box:G.curMatch.box,
                          qy:G.curMatch.qy.slice(), qo:G.curMatch.qo.slice(), qpts:G.curMatch.qpts.slice()});
      if(G.curMatch.win) c.seriesY=(c.seriesY||0)+1; else c.seriesO=(c.seriesO||0)+1;
      G.curMatch=null; G.curMatchChoices=null; G.curMatchComm=null;
      if(c.seriesY>=3){ if(G.curOpp.isAce){ unlock('a_ace'); queueAwaken('aw_ace','aw_ace','屠龙时刻·觉醒'); } c.youLog.push(buildCupEntrySeries(c)); c.idx++; c.seriesY=0; c.seriesO=0; c.seriesGames=[]; if(c.idx>=c.playerPath.length || c.advanced===false) endCup(); else beginPrematch(); }
      else if(c.seriesO>=3){ c.youElim=c.roundNames[Math.min(c.idx,c.roundNames.length-1)]; c.youLog.push(buildCupEntrySeries(c)); c.idx=999; endCup(); }
      else beginPrematch();   // 系列赛未分胜负 → 下一场
    }
  } else {
    var m=G.curMatch;
    G.seasonGames = (G.seasonGames||0) + 1;   // 本赛季比赛数 +1
    G.league.games.push({opp:G.curOpp.name, isAce:!!G.curOpp.isAce, win:m.win, ys:m.ys, os:m.os, box:m.box, strat:m.stratName});
    G.league.idx++;
    G.curMatch=null; G.curMatchChoices=null; G.curMatchComm=null;
    if(G.league.idx>=G.league.schedule.length) endLeague();
    else beginPrematch();
  }
}
function endLeague(){
  var L=G.league, s=G.seasonStats;
  var avg=s.g?Math.round(s.pts/s.g):0;
  G.lastLeague={pos:G.rank, w:s.w, l:s.l, diff:0, avg:avg, period:periodName(), games:L.games.slice()};
  if(s.w===s.g && s.g>0) addHighlight('🏆 '+secLabel()+' 联赛全胜！场均 '+avg+' 分');
  else if(s.w>=Math.ceil(s.g*0.6)) addHighlight('💪 '+secLabel()+' 联赛 '+s.w+'胜'+s.l+'负，渐入佳境');
  if(G.rank===1){ G.axes.result+=4; pushAxisFeed('result',4,'联赛夺冠'); addTrophy('🥇', periodName()+'联赛冠军'); }
  else if(G.rank<=3){ G.axes.result+=2; pushAxisFeed('result',2,'联赛上游'); }
  if(s.g>0 && s.w===s.g) addTrophy('💯', periodName()+'全胜之师');
  G.screen='league'; render();
}
function commentary(m){
  var b=m.box, lines=[];
  if(m.win){
    if(b.pts>=26) lines.push('今天她彻底杀疯了，狂砍 '+b.pts+' 分，率队拿下关键胜利！');
    else if(b.pts>=16) lines.push('稳扎稳打，她用 '+b.pts+' 分的表现带走比赛。');
    else lines.push('虽然数据不炸，但她用防守和团队配合笑到了最后。');
  } else {
    if(Math.abs(m.ys-m.os)<=4) lines.push('惜败！最后时刻就差一口气，但她的 '+b.pts+' 分依旧亮眼。');
    else lines.push('这场被对手压制，'+b.pts+' 分难救主，回去得好好总结。');
  }
  if(b.stl>=4) lines.push('全场比赛她送出 '+b.stl+' 次抢断，防守端存在感拉满。');
  if(b.ast>=6) lines.push(b.ast+' 次助攻盘活全队，是进攻发动机。');
  if(b.blk>=3) lines.push(b.blk+' 次火锅守护篮下，威慑力十足。');
  if(b.tov>=6) lines.push('不过 '+b.tov+' 次失误也提醒她：节奏还得再稳一点。');
  return lines[Math.floor(rng()*lines.length)] || '一场激烈的较量。';
}
/* 三轴成长轨迹曲线（每季末快照：奋斗/成果/友情 三条线） */
function axisTrajectorySVG(){
  var L=G.axisLog; if(!L||!L.effort||L.effort.length<2) return '';
  var n=L.effort.length;
  var eMax=Math.max.apply(null, L.effort.concat([40]));
  var rMax=Math.max.apply(null, L.result.concat([30]));
  function line(arr,max,col,lw){
    var pts=arr.map(function(v,i){
      var x=12+(i/(n-1))*(300-24);
      var y=118-6-(clamp(v/max,0,1))*(118-22);
      return x.toFixed(1)+','+y.toFixed(1);
    }).join(' ');
    return '<polyline points="'+pts+'" fill="none" stroke="'+col+'" stroke-width="'+(lw||2.2)+'" stroke-linejoin="round"/>';
  }
  return '<svg viewBox="0 0 300 124" width="100%">'+
    line(L.effort,eMax,'#e89a2a')+line(L.result,rMax,'#6fae46')+line(L.friend,100,'#e8609a')+'</svg>';
}
/* 技术统计条形图（场均） */
function statsChartSVG(s){
  if(!s||!s.g) return '';
  var a={pts:s.pts/s.g, reb:s.reb/s.g, ast:s.ast/s.g, stl:s.stl/s.g, blk:s.blk/s.g};
  var keys=[['得分',a.pts,'#e8609a'],['篮板',a.reb,'#5aa0e0'],['助攻',a.ast,'#6fae46'],['抢断',a.stl,'#e89a2a'],['盖帽',a.blk,'#3fb0a0']];
  var max=Math.max(a.pts,a.reb,a.ast,a.stl,a.blk,1), w=300,h=130,bw=42,gap=(w-keys.length*bw)/(keys.length+1);
  var bars=keys.map(function(k,i){
    var bh=clamp(k[1]/max*(h-30),2,h-30), x=gap+(bw+gap)*i, y=h-20-bh;
    return '<rect x="'+x+'" y="'+y+'" width="'+bw+'" height="'+bh+'" rx="4" fill="'+k[2]+'"/>'+
      '<text x="'+(x+bw/2)+'" y="'+(y-3)+'" font-size="10" fill="#8a8390" text-anchor="middle">'+k[1].toFixed(1)+'</text>'+
      '<text x="'+(x+bw/2)+'" y="'+(h-6)+'" font-size="10" fill="#5a5260" text-anchor="middle">'+k[0]+'</text>';
  }).join('');
  return '<svg viewBox="0 0 '+w+' '+h+'" width="100%">'+bars+'</svg>';
}
function boxScoreHTML(box){
  var fg=box.fga>0?Math.round(box.fgm/box.fga*100):0;
  var rows=[['得分',box.pts],['篮板',box.reb],['助攻',box.ast],['抢断',box.stl],['盖帽',box.blk],['失误',box.tov],['命中率',fg+'%']];
  return '<div class="boxscore">'+rows.map(function(r){
    return '<div class="bx"><span class="bv">'+r[1]+'</span><span class="bl">'+r[0]+'</span></div>';
  }).join('')+'</div>';
}
/* 队友单场技术统计：由 OVR + 位置属性 + 本场上场时间合成；最终按"全队剩余得分"缩放，
   使全队总分 = 主角分 + 队友分之和，读起来就像真实的技术统计 */
function genMateBox(p, mins){
  var skill=p.m_sk||40, ag=p.m_ag||40, str=p.m_st||40, ht=p.height||170;
  var fat = (p.stam!=null && p.stamMax)? (p.stam/p.stamMax<0.4?0.85:1) : 1;
  var mf = clamp((mins||15)/28, 0.15, 1.5);
  var off = 0.9 + (p.ovr-50)*0.006;
  var pts = Math.round(clamp((4 + (skill*0.10 + ag*0.03 + str*0.02 + ht*0.015)*off*(0.7+rng()*0.5)), 0, 80)*mf);
  var fgPct = clamp(0.28 + skill*0.004 + (p.ptrait==='tech'?0.04:0), 0.2, 0.66);
  var reb = Math.round((1.2 + ht*0.04 + str*0.03)*0.9*(0.7+rng()*0.5)*mf*fat);
  var ast = Math.round((0.6 + skill*0.045 + ag*0.02)*(0.7+rng()*0.5)*mf*fat);
  var stl = Math.round((0.3 + ag*0.03)*(0.6+rng()*0.7)*mf*fat);
  var blk = Math.round((0.2 + ht*0.025 + str*0.025)*(0.5+rng()*0.8)*mf*fat);
  var tov = Math.round(clamp((2.6 - skill*0.02 - ag*0.01)*(0.7+rng()*0.6),0,10)*mf);
  var fga = Math.round(pts*0.9 + 2 + rng()*4);
  var fgm = Math.round(clamp(fga*fgPct,0,fga));
  if(pts>0 && fgm===0) fgm=1;
  return {pts:pts,reb:reb,ast:ast,stl:stl,blk:blk,tov:tov,fgm:fgm,fga:fga};
}
/* 生成本场全队（含主角）技术统计，存入 m.mateBoxes；主角分已含在 m.box 中 */
function buildMateBoxes(m){
  if(!m) return;
  var youPts = (m.box && m.box.pts!=null)? m.box.pts : (m.qpts? m.qpts.reduce(function(a,b){return a+(b||0);},0):0);
  var teamTotal = (m.ys!=null)? m.ys : 0;
  var remain = Math.max(0, teamTotal - youPts);
  var mates = (G.teammates||[]).map(function(p){
    var mins = (p.gameMins!=null)? p.gameMins : roleMid(p);
    return {p:p, mins:mins, box: genMateBox(p, mins)};
  });
  var rawSum = mates.reduce(function(a,x){ return a + x.box.pts; }, 0);
  if(rawSum>0 && remain>0){
    var k = remain/rawSum;
    mates.forEach(function(x){ x.box.pts = Math.max(0, Math.round(x.box.pts*k)); });
  } else if(rawSum>0){
    mates.forEach(function(x){ x.box.pts = 0; });
  }
  m.mateBoxes = mates.map(function(x){
    return {uid:x.p.uid, name:x.p.name, pos:x.p.pos, role:x.p.role, grade:x.p.grade,
            ptrait:x.p.ptrait, ptraitN:x.p.ptraitN, mins:x.mins, box:x.box};
  });
}
/* 全队技术统计（主角 + 全体队友），每人带档位 / 年级 / 上场时间 */
function teamBoxHTML(m){
  if(!m) return '';
  var rows = [];
  rows.push(mateBoxRow('你 · '+G.name, TEMPLATES[G.template].name, '核心', (G.resting?0:G.minutes), m.box, true, G.ptraitN, null));
  (m.mateBoxes||[]).forEach(function(b){
    rows.push(mateBoxRow(b.name, b.pos, (ROLE_DEF[b.role]?ROLE_DEF[b.role].label:(b.role||'球员')), b.mins, b.box, false, b.ptraitN, b.grade));
  });
  return '<div class="team-box">'+rows.join('')+'</div>';
}
function mateBoxRow(name, pos, role, mins, box, isYou, ptraitN, grade){
  if(!box) return '';
  var fg = box.fga>0? Math.round(box.fgm/box.fga*100):0;
  var cells = [['分',box.pts],['板',box.reb],['助',box.ast],['断',box.stl],['帽',box.blk],['误',box.tov],['命中',fg+'%']];
  var cls = isYou? ' you' : '';
  var tag = (ptraitN? '<span class="ftag t-mini">'+ptraitN+'</span>' : '');
  var gd = (grade>=1&&grade<=3)? '<span class="gd">'+['一','二','三'][grade-1]+'年级</span>' : (grade>3?'<span class="gd">毕业</span>':'');
  return '<div class="tbx'+cls+'">'+
    '<div class="tbx-h"><b>'+name+'</b><span class="tbx-pos">'+pos+'</span>'+
      '<span class="tbx-role">'+role+'</span>'+gd+tag+'<span class="tbx-min">⏱ '+mins+'′</span></div>'+
    '<div class="tbx-stats">'+cells.map(function(c){ return '<span class="tbx-c"><i>'+c[1]+'</i>'+c[0]+'</span>'; }).join('')+'</div>'+
  '</div>';
}

/* ===== 校队杯：初中=32强两回合淘汰；高中=32进16小组赛+三局两胜淘汰 ===== */
function cupYouEff(){
  return teamPower() * (1 + G.form*0.05) * (0.9 + G.stats.conf/300) * (0.88 + G.stats.stamina/400);
}
function oppEff(t, isCup){
  var ff = fieldFactor(curYear());
  if(t.isAce){
    // 王牌校以"校队 base"为实力基准（430~550，始终高于所有普通强队），保证它是真正的终极 BOSS、
    // 决赛永远是最硬的一战；若对象未带 base（极少见）则回退到全联盟最高 base。
    var base = (typeof t.base==='number') ? t.base : leagueTopBase();
    // 初中杯略收一格（给认真培养的玩家留窗口）；高中杯是终极关卡，大赛加成拉满
    var cupK = isHigh() ? 1.18 : 1.06;
    return base * (isCup ? cupK : 1.02) * ff;
  }
  return (t.base + rosterBonus(t))*ff;
}
/* 固定种子签表：你的校队 = 上半区 1 号位，王牌校 = 下半区 1 号位。
   两强各守半区，一路赢下去就必然在决赛正面撞上最强王牌校。 */
/* 标准种子签位：玩家=1号种子、王牌校=2号（决赛BOSS），其余队按实力升序填入签位。
   这样玩家每轮对手由弱到强、决赛才遇王牌校，难度平滑且"努力就能走到决赛"的体验可控。 */
function bracketSlotOrder(n){
  if(n===32) return [1,32,17,16,9,24,25,8,5,28,21,12,13,20,29,4,3,30,19,14,11,22,27,6,7,26,23,10,15,18,31,2];
  return [1,16,9,8,5,12,13,4,3,14,11,6,7,10,15,2]; // 16 强淘汰
}
function seedField(teams, youName, bossName, bossObj){
  // teams：不含 you/boss 的对手数组；按 oppEff 升序 → seed3=最强, seedN=最弱（玩家路径由弱到强）
  var opp = teams.map(function(t){ return {ref:t, eff:oppEff(t,true)}; })
                  .sort(function(a,b){ return a.eff-b.eff; });
  var bySeed={};
  bySeed[1]={name:youName, you:true, isAce:false, base:0};
  // BOSS（王牌校）固定为 2 号种子、且以真实校队 base 为实力基准，确保它是总决赛最难的一战
  var bossBase = (bossObj && typeof bossObj.base==='number') ? bossObj.base
               : (teams[0]&&teams[0].base!=null ? Math.max.apply(null,teams.map(function(t){return t.base||0;}))*1.15 : 470);
  bySeed[2]={name:bossName, isAce:true, you:false, base:bossBase};
  var N=opp.length+2;
  for(var s=3;s<=N;s++){ bySeed[s]=opp[N-s].ref; }   // s=3→opp[last]最强, s=N→opp[0]最弱
  var so=bracketSlotOrder(N);
  return so.map(function(sd){ return bySeed[sd]; });
}
function seededField(){
  var others=[], ace=null;
  G.curTeams.forEach(function(t){
    if(t.isAce){ ace=t; }
    // 排除玩家自己的校队：它已作为 1 号种子，不应再作为普通对手（否则会自我对战、且签表尺寸错乱）
    else if(!(t.you || t.name===G.school)) others.push(t);
  });
  // 防御：若玩家正好就读王牌校，curTeams 中会缺少王牌校——改由剩余对手中 base 最高者充当决赛 BOSS
  if(!ace){
    others.sort(function(a,b){ return (b.base||0)-(a.base||0); });
    ace = others.shift() || {name:'王牌校队', base:430, you:false};
    ace.isAce = true;
  }
  return seedField(others, G.school, ace.name, ace);
}
/* 非玩家对局：
   - 王牌校是剧本里的终极 BOSS——它在玩家之外的对局里永远晋级（确定性），确保"决赛屠龙"成为固定终章；
   - 其余对局按实力决定性晋级（确定性），避免冷门打乱"由弱到强"的难度曲线；
   玩家自己的比赛仍由 genGame 真实模拟，保留不确定性与翻盘可能。 */
function simOtherPair(a, b){
  if(a.isAce || b.isAce){
    if(a.isAce && b.isAce) return rng()<0.5 ? a : b;   // 双王牌相遇（理论上不会触发）
    return a.isAce ? a : b;
  }
  var we=oppEff(a, true), oe=oppEff(b, true);
  return we>=oe ? a : b;
}
/* 按签表顺序两两配对（不再洗牌），胜者按原顺序进入下一轮，保持半区结构 */
function pairSeq(cur){
  var pairs=[];
  for(var i=0;i<cur.length;i+=2){
    var a=cur[i], b=cur[i+1];
    if(a.you||b.you) pairs.push({hasYou:true, you:a.you?a:b, opp:a.you?b:a});
    else pairs.push({hasYou:false, a:a, b:b});
  }
  return pairs;
}
function simTwoLeg(youE, oppE, oOffMul, oDefMul){
  var l1=simScore(youE,oppE,null,oOffMul,oDefMul), l2=simScore(youE,oppE,null,oOffMul,oDefMul);
  var ay=l1.y+l2.y, ao=l1.o+l2.o;
  var win = ay>ao || (ay===ao && rng() < (0.5 + G.stats.conf/400));
  return {l1:l1, l2:l2, ay:ay, ao:ao, win:win};
}
function simBO3(youE, oppE, oOffMul, oDefMul){
  var games=[]; var yw=0, ow=0;
  for(var i=0;i<3 && (yw<2 && ow<2); i++){
    var s=simScore(youE,oppE,null,oOffMul,oDefMul); games.push(s); if(s.win) yw++; else ow++;
  }
  return {games:games, yw:yw, ow:ow, win: yw>ow};
}
function simBO5(youE, oppE, oOffMul, oDefMul){
  var games=[]; var yw=0, ow=0;
  for(var i=0;i<5 && (yw<3 && ow<3); i++){
    var s=simScore(youE,oppE,null,oOffMul,oDefMul); games.push(s); if(s.win) yw++; else ow++;
  }
  return {games:games, yw:yw, ow:ow, win: yw>ow};
}
function startCup(){
  G.curTeams = isHigh() ? G.highTeams : G.midTeams;
  G.ctx='cup';
  G.seasonStats={g:0,pts:0,reb:0,ast:0,stl:0,blk:0,tov:0,fgm:0,fga:0,w:0,l:0};
  if(!isHigh()) startCupMid();
  else startCupHigh();
}
/* 初中杯：32 强两回合（主客场）淘汰。玩家固定上半区 1 号位，王牌校下半区 1 号位。
   干跑整张签表（玩家默认晋级）以确定玩家每一轮的对手，保证决赛撞上王牌校。 */
function startCupMid(){
  var field=seededField();
  field.forEach(function(t){ if(!t.you){ t.injMul=(rng()<0.14?0.82:1); t.moraleMul=(rng()<0.30?(rng()<0.5?1.12:0.9):1); } });
  var cur=field, path=[];
  while(cur.length>1){
    var pairs=pairSeq(cur), next=[], youOpp=null;
    pairs.forEach(function(p){ if(p.hasYou){ youOpp=p.opp; next.push({you:true,name:G.school}); } else next.push(simOtherPair(p.a,p.b)); });
    if(youOpp) path.push(youOpp);
    cur=next;
  }
  G.cup={isHigh:false, isTwoLeg:true, playerPath:path, idx:0, youLog:[],
         roundNames:['32强','16强','八强','四强','决赛'].slice(0,path.length),
         champion:cur[0].name, dryChamp:cur[0].name, youChamp:false, youElim:null, advanced:true, group:null};
  G.teamMorale=clamp((G.teamMorale||0)+(rng()-0.5)*0.6,-2,2);
  beginPrematch();
}
/* 高中杯：32 进 16 小组赛 + 三局两胜淘汰。小组赛自动模拟并展示，玩家 3 场小组战为焦点；
   之后 16 强淘汰（玩家固定上半区、王牌校下半区）走交互流程。 */
function startCupHigh(){
  var field=seededField();
  field.forEach(function(t){ if(!t.you){ t.injMul=(rng()<0.14?0.82:1); t.moraleMul=(rng()<0.30?(rng()<0.5?1.12:0.9):1); } });
  var groups=[]; for(var i=0;i<32;i+=4) groups.push(field.slice(i,i+4));
  var grpNames=['A','B','C','D','E','F','G','H'];
  var adv=[], playerGroup=null, playerAdvanced=false;
  groups.forEach(function(g,gi){
    var tbl=groupTable(g, teamPower());
    var ti=-1; for(var k=0;k<tbl.length;k++){ if(tbl[k].isAce){ ti=k; break; } }
    if(ti>1){ var tmp=tbl[1]; tbl[1]=tbl[ti]; tbl[ti]=tmp; }
    if(gi===0 && g[0].you){
      playerGroup={grp:grpNames[gi], rows:tbl.map(function(r){return {name:r.name,you:r.you,isAce:r.isAce,w:r.w};}),
                   pos:tbl.findIndex(function(r){return r.you;})+1};
      playerAdvanced=playerGroup.pos<=2;
    }
    adv.push(tbl[0].team); adv.push(tbl[1].team);
  });
  // 16 强交叉配对改为"标准升序种子"：玩家=1号、王牌校=2号（决赛），其余由弱到强，难度平滑
  var youObj=null, ace16=null, others16=[];
  adv.forEach(function(t){
    if(t.you || t.name===G.school) youObj=t;
    else if(t.isAce) ace16=t;
    else others16.push(t);
  });
  if(!ace16){
    others16.sort(function(a,b){ return (b.base||0)-(a.base||0); });
    ace16 = others16.shift() || {name:'王牌校队', base:430};
    ace16.isAce = true;
  }
  var ko = seedField(others16, G.school, ace16.name, ace16);
  var cur=ko, path=[];
  while(cur.length>1){
    var pairs=pairSeq(cur), next=[], youOpp=null;
    pairs.forEach(function(p){ if(p.hasYou){ youOpp=p.opp; next.push({you:true,name:G.school}); } else next.push(simOtherPair(p.a,p.b)); });
    if(youOpp) path.push(youOpp);
    cur=next;
  }
  G.cup={isHigh:true, isTwoLeg:false, playerPath:path, idx:0, youLog:[],
         roundNames:['16强','八强','四强','决赛'].slice(0,path.length),
         champion:cur[0].name, dryChamp:cur[0].name, youChamp:false, youElim:null,
         advanced:playerAdvanced, group:playerGroup,
         seriesY:0, seriesO:0, seriesGames:[]};
  if(!playerAdvanced) G.cup.youElim='小组赛';
  G.teamMorale=clamp((G.teamMorale||0)+(rng()-0.5)*0.6,-2,2);
  beginPrematch();
}
function buildCupEntry(res, opp, round){
  if(G.cup.isTwoLeg){
    return {type:'twoleg', round:round, opp:opp.name, isAce:!!opp.isAce,
            l1:res.twoleg.l1, l2:res.twoleg.l2, ay:res.ys, ao:res.os, win:res.win, box:res.box};
  }
  return {type:'bo5', round:round, opp:opp.name, isAce:!!opp.isAce,
          games:(res.bo5?res.bo5.games:null), yw:(res.bo5?res.bo5.yw:3), ow:(res.bo5?res.bo5.ow:0), win:res.win, box:res.box};
}
/* 高中杯五局三胜（逐场交互系列赛）的赛果记录：每场都是四节，seriesGames 记录逐场比分与四节分布 */
function buildCupEntrySeries(c){
  var opp = G.curOpp;
  return {type:'bo5', round:c.roundNames[Math.min(c.idx,c.roundNames.length-1)], opp:opp.name, isAce:!!opp.isAce,
          seriesGames:c.seriesGames, yw:c.seriesY, ow:c.seriesO, win:c.seriesY>=3, box:(c.seriesGames.length?c.seriesGames[c.seriesGames.length-1].box:null)};
}
function endCup(){
  var c=G.cup; c.final=true;
  c.youChamp = (c.idx>=c.playerPath.length && !c.youElim && c.advanced!==false);
  if(c.youChamp){ unlock(c.isHigh?'a_cup_high':'a_cup'); queueAwaken('aw_cup','aw_cup','冠军之夜·觉醒'); addHighlight('🏆 '+(c.isHigh?'高中':'初中')+'校队杯夺冠！'); G.axes.result += c.isHigh?7:4; pushAxisFeed('result', c.isHigh?7:4, (c.isHigh?'高中':'初中')+'杯夺冠'); }
  else { addHighlight('😣 '+(c.isHigh?'高中':'初中')+'杯止步'+(c.youElim||'小组赛')); }
  G.screen='cup'; render();
}
function runCupTwoLeg(field, youE){
  var roundNames=['32强','16强','八强','四强','决赛'];
  var rd=0, cur=field;
  while(cur.length>1){
    var pairs=pairSeq(cur); var next=[];
    pairs.forEach(function(p){
      if(p.hasYou){
        var tr2 = TRAIT_BY[p.opp.trait] || TRAIT_BY.allround;
        var res=simTwoLeg(youE, oppEff(p.opp, true), tr2.offMul||1, tr2.defMul||1);
        G.cup.youLog.push({type:'twoleg', round:roundNames[rd], opp:p.opp.name, isAce:!!p.opp.isAce, l1:res.l1, l2:res.l2, ay:res.ay, ao:res.ao, win:res.win});
        if(res.win){ next.push({you:true, name:G.school}); if(p.opp.isAce){ unlock('a_ace'); queueAwaken('aw_ace','aw_ace','屠龙时刻·觉醒'); } }
        else { G.cup.youElim=roundNames[rd]; next.push(p.opp); }
      } else {
        next.push(simOtherPair(p.a, p.b));
      }
    });
    cur=next; rd++;
  }
  G.cup.champion = cur[0].name;
  G.cup.youChamp = !!cur[0].you;
  if(G.cup.youChamp) unlock('a_cup');
  if(G.cup.youChamp){ addHighlight('🏆 初中校队杯夺冠！'); addTrophy('🏆','初中校队杯冠军'); }
  else addHighlight('😣 初中杯止步'+G.cup.youElim+'，明年再来');
}
function runCupHigh(field, youE){
  // 8 组×4，小组单循环，各组前 2 进 16。你在 A 组（上半区），王牌校在 E 组（下半区）。
  var groups=[]; for(var i=0;i<32;i+=4) groups.push(field.slice(i,i+4));
  var firsts=[], seconds=[];
  var grpNames=['A','B','C','D','E','F','G','H'];
  groups.forEach(function(g, gi){
    var tbl = groupTable(g, youE);
    // 王牌校保证小组出线（夺冠热门剧本，只会被你亲手淘汰）
    var ti=-1; for(var k=0;k<tbl.length;k++){ if(tbl[k].isAce){ ti=k; break; } }
    if(ti>1){ var tmp=tbl[1]; tbl[1]=tbl[ti]; tbl[ti]=tmp; }
    firsts.push(tbl[0].team); seconds.push(tbl[1].team);
    var youRow=null; for(var k=0;k<tbl.length;k++){ if(tbl[k].you){ youRow=tbl[k]; break; } }
    if(youRow){
      var pos = tbl.indexOf(youRow)+1;
      G.cup.youLog.push({type:'group', grp:grpNames[gi], w:youRow.w, l:g.length-1-youRow.w, pos:pos, adv:pos<=2});
      if(pos>2) G.cup.youElim='小组赛';
    }
  });
  // 16 强交叉配对：A1-B2 / B1-A2 / C1-D2 / D1-C2（上半区），E~H 同理（下半区）
  var cur=[firsts[0],seconds[1], firsts[1],seconds[0], firsts[2],seconds[3], firsts[3],seconds[2],
           firsts[4],seconds[5], firsts[5],seconds[4], firsts[6],seconds[7], firsts[7],seconds[6]];
  var roundNames=['16强','八强','四强','决赛'];
  var rd=0;
  while(cur.length>1){
    var pairs=pairSeq(cur); var next=[];
    pairs.forEach(function(p){
      if(p.hasYou){
        var tr5 = TRAIT_BY[p.opp.trait] || TRAIT_BY.allround;
        var res=simBO5(youE, oppEff(p.opp, true), tr5.offMul||1, tr5.defMul||1);
        G.cup.youLog.push({type:'bo5', round:roundNames[rd], opp:p.opp.name, isAce:!!p.opp.isAce, games:res.games, yw:res.yw, ow:res.ow, win:res.win});
        if(res.win){ next.push({you:true, name:G.school}); if(p.opp.isAce){ unlock('a_ace'); queueAwaken('aw_ace','aw_ace','屠龙时刻·觉醒'); } }
        else { G.cup.youElim=roundNames[rd]; next.push(p.opp); }
      } else {
        next.push(simOtherPair(p.a, p.b));
      }
    });
    cur=next; rd++;
  }
  G.cup.champion = cur[0].name;
  G.cup.youChamp = !!cur[0].you;
  if(G.cup.youChamp) unlock('a_cup_high');
  if(G.cup.youChamp){ addHighlight('🏆 高中校队杯封王！'); addTrophy('👑','高中校队杯冠军'); }
  else addHighlight('😣 高中杯止步'+G.cup.youElim);
}
function groupTable(g, youE){
  var W={}; g.forEach(function(t){ W[t.name]=0; });
  for(var i=0;i<g.length;i++) for(var j=i+1;j<g.length;j++){
    var a=g[i], b=g[j];
    var sa=a.you?youE:oppEff(a, true), sb=b.you?youE:oppEff(b, true);
    var s=simScore(sa,sb);
    if(s.win) W[a.name]++; else W[b.name]++;
  }
  return g.map(function(t){ return {name:t.name, w:W[t.name], you:t.you, isAce:t.isAce, team:t}; })
          .sort(function(x,y){ return y.w-x.w; });
}
function cupNext(){
  if(G.screen!=='cup'||!G.cup||G.cup.final) return;
  G.cup.displayIdx++;
  if(G.cup.displayIdx >= G.cup.youLog.length) G.cup.final=true;
  render();
}
function cupContinue(){ postSeason(); }

/* 季末推进：回到下一季训练或结局 */
function seasonAverages(s){
  var g=s.g||0; if(!g) return null;
  return { ppg:s.pts/g, rpg:s.reb/g, apg:s.ast/g, spg:s.stl/g, bpg:s.blk/g,
           winRate:s.w/g,
           score:(s.pts/g)+(s.reb/g)*0.8+(s.ast/g)*1.1+(s.stl/g)*1.4+(s.blk/g)*1.4+(s.w/g)*15 };
}
/* 每赛季评选：MVP（综合评分高且胜率够）与进步奖（较上季明显提升） */
function evaluateSeasonAwards(){
  var s=G.seasonStats, avg=seasonAverages(s);
  G.seasonAwards=[];
  if(!avg) return;
  if(avg.winRate>=0.55 && avg.score>=20){
    G.seasonAwards.push({key:'mvp', t:'🏅 赛季MVP', d:'教练组一致评选你为最有价值球员'});
    G.stats.pop=Math.max(0,G.stats.pop+5); G.stats.conf=Math.max(0,G.stats.conf+4);
    G.teamMorale=clamp((G.teamMorale||0)+0.5,-3,3); G.axes.result+=3; pushAxisFeed('result',3,'赛季MVP');
    addHighlight('🏅 当选赛季MVP！人气 +5，自信 +4，全队士气大涨');
    diary(secLabel(),'教练组评选你为赛季MVP——你的表现征服了所有人。');
  }
  var last=G.lastSeasonAvg;
  if(last && (avg.score-last.score>=4 || avg.ppg-last.ppg>=4)){
    G.seasonAwards.push({key:'imp', t:'📈 进步奖', d:'本赛季各项数据较上季显著提升'});
    G.stats.conf=Math.max(0,G.stats.conf+3); G.stats.pop=Math.max(0,G.stats.pop+2);
    G.stamCapBonus=Math.min(40,(G.stamCapBonus||0)+2); G.stats.stamina=stamCap();
    G.axes.result+=2; pushAxisFeed('result',2,'进步奖');
    addHighlight('📈 荣获进步奖！自信 +3，体力上限 +2，越来越多人看到你的成长');
    diary(secLabel(),'你拿下了本赛季的进步奖——一步一个脚印，越来越强。');
  }
  G.lastSeasonAvg=avg;
}
function postSeason(){
  // —— 成长回顾快照：记录本季初值，季末用于展示"个人+团队成长"的满足感 ——
  var _pre = {skill:G.stats.skill, strength:G.stats.strength, agility:G.stats.agility, stamina:G.stats.stamina,
              height:G.stats.height, power:power(G.stats), teamOvr:avgMateOvr(), rank:G.rank};
  G.season++; G.age = 12 + G.season*0.25; G.year = 2010 + Math.floor(G.season*0.25);
  if(G.season % 4 === 0 && G.season < G.total) advanceRoster();   // 学年末：新秀入队、老将退役（每学年 10%~40% 换血）
  G.specialStage=G.season; G.specialEvents={};   // 每个新阶段重置"每队友 2 段特殊剧情"的额度
  applySchoolGrowth(G.season);   // 各校按"成长剧本"在本季推进实力，联赛格局随之演变
  applyPlayerGrowth(G.season);   // 球员个人（含你校队友）逐季成长：战绩激励 + 随机基础成长
  growBio();   // 每季自然生长（身高/体重/臂展/腿长/鞋码/骨龄 的基础成长值）
  // 赛季"基础成长"：即便本季只做了少量训练，一个赛季的实战与日常也会让核心篮球属性稳步提升，
  // 避免中段（尤其 13–15 岁低谷期）出现"成长停滞感"，让能力曲线持续向上、成就感更扎实。
  (function(){
    var bg = {skill:0.6, strength:0.6, agility:0.6, stamina:0.4};
    var bgMul = (inSlump(G.season)?diffCfg().slump:1) * (1 + G.form*0.05);
    // ③ 年龄成长曲线 + ① 边际递减：低龄/青春期被动成长快、高龄趋缓；属性越高增益越小
    for(var bk in bg){
      var v = bg[bk]*bgMul * dimRet(bk, G.stats[bk]) * ageWin(bk, G.age);
      G.stats[bk] = Math.max(0, G.stats[bk] + v);
    }
  })();
  G.stats.stamina = stamCap();   // 休赛期充分休整，体力回到当前上限
  (G.teammates||[]).forEach(function(p){ if(p.stamMax!=null) p.stam = p.stamMax; });   // 队友：同样休赛期满血
  if(G.curOpp && G.curOpp.roster){ G.curOpp.roster.forEach(function(p){ if(p.stamMax!=null) p.stam = p.stamMax; }); } // 对手：同样休赛期满血
  G.trainLoad = 0;              // ② 休赛期恢复：清零赛季内累积的训练负荷
  advanceWorld();
  computeRank();
  computeSeasonStory();   // 本季战力风云（崛起/掉队），让联赛格局随成长剧本逐季演变、可见可感
  computePlayerStory();   // 联盟球星涌现（巨人中锋长成 2m+ 等）高光提示
  checkMilestones();
  evaluateSeasonAwards();   // 每季末评选 MVP / 进步奖
  // —— 本季成长回顾（个人属性 + 全队平均 OVR + 联赛排名环比），供主界面"成长回顾"卡片展示 ——
  G.lastGrowthRecap = {
    skill:+(G.stats.skill-_pre.skill).toFixed(1),
    strength:+(G.stats.strength-_pre.strength).toFixed(1),
    agility:+(G.stats.agility-_pre.agility).toFixed(1),
    stamina:+(G.stats.stamina-_pre.stamina).toFixed(1),
    height:+(G.stats.height-_pre.height).toFixed(1),
    power:Math.round(power(G.stats)-_pre.power),
    teamOvr:Math.round(avgMateOvr()-_pre.teamOvr),
    rank:G.rank, prevRank:_pre.rank,
    powerNow:Math.round(power(G.stats)), teamOvrNow:Math.round(avgMateOvr())
  };
  if(!G.banner && G.prevRank!=null && G.rank < G.prevRank){
    G.banner = '↑ 校队联赛上升 '+(G.prevRank-G.rank)+' 位，现第 '+G.rank+'/32';
  }
  G.prevRank = G.rank;
  if(G.rank < G.bestRank) G.bestRank = G.rank;
  // 日常羁绊生长（赛马娘式"一起训练"的累积）：让关系网在自然相处中稳步加深，
  // 即使玩家不刻意经营，羁绊阈值事件也会在中段陆续触发，保证"关系网影响结局"的厚度
  if(G.friends.xiaotong!=null) G.friends.xiaotong = clamp((G.friends.xiaotong||0)+3, 0, 100);
  if(G.friends.coach!=null) G.friends.coach = clamp((G.friends.coach||0)+2.5, 0, 100);
  if(G.friends.senpai!=null) G.friends.senpai = clamp((G.friends.senpai||0)+3.5, 0, 100);
  if(G.friends.kouhai!=null) G.friends.kouhai = clamp((G.friends.kouhai||0)+3.5, 0, 100);
  // 美少女梦工厂式·年度反思：每跨过一个学年，在赛季结算处直接回望一次。
  // 放在 postSeason（每季必执行）而非依赖 commit 槽，彻底杜绝"被其他事件吞掉而遗漏"。
  var newYr = Math.floor(G.season/4);
  if(newYr > (G.lastReflectYr||0) && G.season < G.total){
    G.lastReflectYr = newYr;
    G.event = getNode('yearReflect'); G.eventIsStory=false; G.pendingSeason=G.season;
    G.screen='event'; render(); return;
  }
  // 赛马娘式"羁绊裂痕"/美少女梦工厂式"关系波动"：关系熟络即触发一次矛盾→化解弧。
  // 同样放在 postSeason 这处可靠出口，保证中段必有摩擦与和解的戏剧起伏（独立于 commit 空闲槽）。
  var cd = conflictDue();
  if(cd && G.season < G.total){
    G.conflictFired[cd]=true;
    G.event = getNode(cd); G.eventIsStory=false; G.pendingSeason=G.season;
    G.screen='event'; render(); return;
  }
  // 赛马娘式"羁绊阈值事件"：关系跨档即触发（每档一次），与矛盾弧共用 postSeason 这处可靠出口。
  // 旧实现把它放在 commit() 内、位于主线叙事与事件队列之后，导致每个赛季的空闲事件槽都被占满，
  // 羁绊阈值事件几乎从不触发（且连带 sp_b3/kb_b3 的"传承/榜样"觉醒也失踪）。现改在 postSeason 触发，
  // 保证即便玩家不刻意经营，羁绊阈值事件也会在中段陆续冒出来。
  if(fireBondOrYear(G.season)) return;
  var ahead = power(G.stats) >= rivalTopPower();
  if(G.prevAhead===false && ahead && !inSlump(G.season)){ G.banner='你反超了同届最强的那批人——现在，你就是标杆。'; queueFanfare('🔥','跃居同届第一人！','你压过了所有同龄强手，登顶在望', 'power'); }
  G.prevAhead = ahead;
  // 蜕变：跨过 13–15 岁低谷后，在 15 岁（season 14）触底反弹
  if(G.season>=14 && !G.breakDone){ transformBreak(); }
  // 三轴轨迹快照（每季末记录一次，用于结局的成长曲线）
  syncAxes();
  G.axisLog.effort.push(G.axes.effort);
  G.axisLog.result.push(G.axes.result);
  G.axisLog.friend.push(G.axes.friend);
  checkMilestones();   // 季末复核：更衣室之魂 / 全明星 / 传奇女王 等综合成就
  if(G.season>=G.total){ G.screen='ending'; }
  else { G.screen='main'; genOffer(); }
  render();
}

/* 学年末阵容更替：三年级退役，一年级涌入，整体 10%~40% 换血（初中/高中每年都发生） */
function advanceRoster(){
  if(!G.teammates || !G.teammates.length) return;
  var size = G.rosterSize || G.teammates.length;
  // 1) 升年级；三年级（grade≥4）毕业离队
  G.teammates.forEach(function(p){ if(p.grade!=null) p.grade++; });
  var grads = G.teammates.filter(function(p){ return p.grade>3; });
  var kept = G.teammates.filter(function(p){ return p.grade<=3; });
  // 2) 额外换血：在留队者中随机淘汰若干，使本学年总变动落在 10%~40%（扣除自然毕业人数）
  var churnTarget = Math.round(size * (0.10 + rng()*0.30));
  var removeN = Math.max(0, churnTarget - grads.length);
  removeN = Math.min(removeN, Math.max(0, kept.length-1));
  // 优先让高年级（二年级为主）流动，更自然
  kept.sort(function(a,b){ return (b.grade||1)-(a.grade||1) + (rng()-0.5); });
  var extraOut = kept.slice(0, removeN);
  var rest = kept.slice(removeN);
  var leftNames = grads.map(function(p){return p.name;}).concat(extraOut.map(function(p){return p.name;}));
  // 3) 招入新一年级，补满到原规模
  var need = Math.max(0, size - rest.length);
  var school = (isHigh()? G.allHigh : G.allMid).filter(function(t){ return t.name===G.school; })[0];
  var newcomers = [];
  for(var i=0;i<need;i++){
    var rookie = genRookieMate(school);
    if(rookie) newcomers.push(rookie);
  }
  G.teammates = rest.concat(newcomers);
  assignRoles(G.teammates);          // 重新分配档位（副核/主力/轮换/奇兵）
  G.lineup = defaultLineup();
  if(leftNames.length) diary(secLabel(), '赛季更迭：'+leftNames.slice(0,3).join('、')+(leftNames.length>3?(' 等 '+leftNames.length+' 人'):'')+' 告别球队，新秀入队。');
}
/* 生成一名新秀（基于当前所选学校的实力，随机年级=1） */
function genRookieMate(school){
  if(!school) return null;
  var isH = isHigh();
  var salt = hashStr(school.name + '|' + G.season + '|' + (school.roster? school.roster.length:0) + '|' + Math.floor(rng()*1e6));
  var fresh = genRoster(school.name, school.base, salt, school.trait, isH);
  if(!fresh || !fresh.length) return null;
  var rp = fresh[Math.floor(rng()*fresh.length)];
  var mk = makeTeammates([rp])[0];
  if(mk){ mk.grade = 1; mk.uid = 'rook-' + G.season + '-' + Math.floor(rng()*1e9); }   // 新秀为一年级，uid 唯一
  return mk;
}
/* 蜕变：低谷后触底反弹 */
function transformBreak(){
  var st=G.stats, big=G.crisisHandled;
  var burst = big
    ? {height:2.5, skill:12, strength:9, agility:8, conf:9, stamina:6, pop:5}
    : {height:0.8, skill:4, strength:3, agility:3, conf:3};
  applyEff(burst);
  G.breakDone=true;
  addHighlight(big? '🌟 低谷蜕变！全面进化，强势归来' : '🌱 慢慢找回了状态');
  if(big){
    G.banner='🌟 蜕变！她跨过了瓶颈期，技术、力量、自信全面暴涨，一举反超同届那批人！';
    unlock('a_break');
    storyLine(secLabel(),'那段瓶颈期没有白熬——她像换了个人，全面进化，把落下的全追了回来。');
  }
}

/* ===== 事件树：主线(六年球风路线) + 三条支线 + 低谷危机 ===== */
var ROUTES = {
  "scorer":{name:"得分手",icon:"🏹",color:"#e8609a",chapters:[{t:"初窥手感"},{t:"苦练三分"},{t:"关键一投"},{t:"得分王"},{t:"包夹考验"},{t:"封神一战"}]},
  "playmaker":{name:"组织核心",icon:"🎯",color:"#4f8cff",chapters:[{t:"初识视野"},{t:"节奏大师"},{t:"一传致命"},{t:"助攻王"},{t:"失误低谷"},{t:"统领全场"}]},
  "defender":{name:"防守铁闸",icon:"🛡️",color:"#3aa76d",chapters:[{t:"初识卡位"},{t:"盖帽时机"},{t:"抢断嗅觉"},{t:"防守支柱"},{t:"体能极限"},{t:"铁血防线"}]},
  "allround":{name:"全能领袖",icon:"👑",color:"#c79a3a",chapters:[{t:"全能起点"},{t:"短板之痛"},{t:"串联全队"},{t:"领袖气质"},{t:"重压时刻"},{t:"传奇之路"}]}
};
function setRoute(key){ if(!(ROUTES&&ROUTES[key])) return; G.route=key; if(!G.routeScore) G.routeScore={scorer:0,playmaker:0,defender:0,allround:0};
  G.routeSwitchedThisYear=false; }
function addRouteScoreFromMatch(box){
  if(!G.routeScore) G.routeScore={scorer:0,playmaker:0,defender:0,allround:0};
  var s=G.routeScore, b=box||{};
  s.scorer += (b.pts||0)*0.5;
  s.playmaker += (b.ast||0)*1.0;
  s.defender += ((b.reb||0)+(b.blk||0)+(b.stl||0))*0.6;
  s.allround += ((b.pts||0)*0.2 + (b.ast||0)*0.4 + ((b.reb||0)+(b.blk||0)+(b.stl||0))*0.25 + (b.fgm||0)*0.1);
}
function routeSwitchDue(){
  if(!G.route || (G.routeStage||0)>=6 || G.routeSwitchedThisYear) return null;
  var cur=G.routeScore[G.route]||0, best=null, bv=-1;
  for(var k in G.routeScore){ if(k!==G.route && G.routeScore[k]>bv){ bv=G.routeScore[k]; best=k; } }
  if(best && bv-cur>=15){ return 'route_switch'; }
  return null;
}
function routeSelHTML(){
  var keys=Object.keys(ROUTES), cards=keys.map(function(k){ var r=ROUTES[k];
    return '<div style="border:2px solid '+r.color+';border-radius:14px;padding:14px;cursor:pointer;background:#fff;box-shadow:0 2px 10px rgba(0,0,0,.06)" onclick="pickRoute(\''+k+'\')">' + '<div style="font-size:26px;line-height:1">'+r.icon+'</div>' + '<div style="font-weight:700;font-size:15px;margin-top:6px;color:'+r.color+'">'+r.name+'</div>' + '<div style="font-size:12px;color:#6a5f70;margin-top:6px;line-height:1.5">'+r.chapters[0].t+' … 共 '+r.chapters.length+' 章</div></div>';
  }).join('');
  return '<div class="overlay"><div class="modal" style="max-width:580px"><h2 style="margin:0 0 4px">选择你的球风路线</h2>'
    + '<p class="muted" style="margin:0 0 16px">六年的成长主线由你主导 —— 选定后可随打法自然转向。</p>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">'+cards+'</div></div></div>';
}
function pickRoute(key){ if(!ROUTES[key]) return; setRoute(key); G.screen='main'; render(); }
