  frd_train2:{t:'姐妹花的默契', who:'晓彤', d:'两人配合越来越默契，场上一个眼神就懂。',
    c:[{l:'击掌约定冲主力', hint:'友情 +2，自信 +2', eff:{conf:2, fr_xiaotong:2}}]},
